import React, { useState, useEffect, useMemo } from 'react';
import {
  Dialog, DialogContent, Button, Typography, Box, Chip, TextField,
  InputAdornment, Stack, IconButton, Avatar, Divider, Paper, Tooltip,
  Accordion, AccordionSummary, AccordionDetails, Grid,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import SearchIcon from '@mui/icons-material/Search';
import CloseIcon from '@mui/icons-material/Close';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import DashboardIcon from '@mui/icons-material/Dashboard';
import PeopleIcon from '@mui/icons-material/People';
import ContactPhoneIcon from '@mui/icons-material/ContactPhone';
import SearchIcon2 from '@mui/icons-material/Search';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import AssessmentIcon from '@mui/icons-material/Assessment';
import CategoryIcon from '@mui/icons-material/Category';
import InputIcon from '@mui/icons-material/Input';
import MailIcon from '@mui/icons-material/Mail';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import SettingsIcon from '@mui/icons-material/Settings';
import SmartToyIcon from '@mui/icons-material/SmartToy';
import KeyboardIcon from '@mui/icons-material/Keyboard';
import LightbulbIcon from '@mui/icons-material/Lightbulb';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';

const HELP_SECTIONS = [
  {
    id: 'dashboard',
    icon: <DashboardIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#6366f1',
    title: 'داشبورد',
    content: [
      'نمای کلی سازمان: تعداد پرسنل، نرخ خروج و ورود، میانگین سنی و هشدارها.',
      'کارت‌های KPI لحظه‌ای آمار را در بالای صفحه نشان می‌دهند.',
      'هشدارها: قراردادهای در شرف انقضا، مدارک منقضی و فعالیت‌های اخیر.',
    ],
  },
  {
    id: 'employees',
    icon: <PeopleIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#ec4899',
    title: 'پرسنل',
    content: [
      'لیست، جستجو و فیلتر پرسنل با avatars و وضعیت رنگی.',
      'افزودن پرسنل: فرم تک‌صفحه با کارت‌های شیشه‌ای (فردی، تماس، شغلی، ارزیابی، سوابق کاری، مدارک).',
      'پرونده پرسنلی: ۶ تب کامل — فردی، شغلی، دریافتی‌ها، کارکرد، تغییرات، مدارک.',
      'عکس پرسنلی: در فرم یا تب مدارک آپلود می‌شود و در تمام بخش‌ها نمایش داده می‌شود.',
      'تغییرات شغلی: تاریخچه ارتقا/تنزل/تغییر دپارتمان/حقوق + نسخه‌های قرارداد.',
    ],
  },
  {
    id: 'phonebook',
    icon: <ContactPhoneIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#10b981',
    title: 'دفترچه تلفن',
    content: [
      'کارت‌های تماس شیشه‌ای: عکس، موبایل، تلفن، ایمیل، آدرس و تماس اضطراری.',
      'دو نمای کارتی و لیستی + جستجو و فیلتر دپارتمان.',
      'خروجی اکسل برای استفاده آفلاین.',
    ],
  },
  {
    id: 'search',
    icon: <SearchIcon2 sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#f59e0b',
    title: 'جستجوی پیشرفته',
    content: [
      'جستجو همزمان در پرسنل و مدارک.',
      'فیلترهای ترکیبی: دپارتمان، عنوان شغلی، محل، جنسیت، تأهل، وضعیت، نوع مدرک.',
      'جستجوی فازی (Trigram) روی PostgreSQL — حتی نام ناقص پیدا می‌شود.',
    ],
  },
  {
    id: 'orgchart',
    icon: <AccountTreeIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#8b5cf6',
    title: 'چارت سازمانی',
    content: [
      'درخت سلسله‌مراتبی با اتصالات خودکار و کارت‌های رنگی بر اساس عمق.',
      'تمرکز بر شاخه: انتخاب یک گره → زنجیره بالادستی + زیرمجموعه کامل.',
      'ویرایش: افزودن/ویرایش/حذف جایگاه + تخصیص نفرات به هر پست.',
      'چاپ/PDF: کل چارت یا شاخه انتخابی با مقیاس خودکار و بدون برش.',
    ],
  },
  {
    id: 'reports',
    icon: <AssessmentIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#3b82f6',
    title: 'گزارشات',
    content: [
      '۱۵+ نمودار تعاملی: ترکیب جنسیتی، دپارتمان‌ها، عنوان شغلی، محل، بیمه، سن، نرخ خروج.',
      'روند استخدام ۱۲ ماه + توزیع سنی + نوبت کاری.',
      'تولدهای ۷ روز آینده (شمسی) + خلاصه مکاتبات و حقوق.',
      'دستیار منابع انسانی برای پرسش و پاسخ هوشمند متنی.',
    ],
  },
  {
    id: 'definitions',
    icon: <CategoryIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#14b8a6',
    title: 'تعاریف اولیه',
    content: [
      'مشخصات شرکت: لوگو، اطلاعات حقوقی، تماس و آدرس.',
      'دپارتمان‌ها (سلسله‌مراتبی)، عناوین شغلی (با سطح)، محل‌ها، لیست بیمه.',
      'انواع مدارک و انواع قرارداد (پویا — در کل برنامه استفاده می‌شوند).',
      'سازمان‌های خارجی: مالیات، تأمین اجتماعی، بانک و ...',
    ],
  },
  {
    id: 'data-entry',
    icon: <InputIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#f97316',
    title: 'ورود اطلاعات',
    content: [
      '۵ تب: مرخصی، غیبت، حقوق، مزایا، کسورات.',
      'حقوق: ثبت فیش ماهانه، درون‌ریزی گروهی اکسل و لیست.',
      'مزایای رفاهی: عیدی، بن کارت، وام و ...',
      'تراکنش‌های اخیر در پایین صفحه.',
    ],
  },
  {
    id: 'correspondences',
    icon: <MailIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#06b6d4',
    title: 'مکاتبات',
    content: [
      'نامه‌های وارده، صادره، ابلاغ‌ها و فرم‌ها.',
      'هر مورد: شماره، تاریخ شمسی، موضوع، اولویت و پیوست قابل دانلود.',
      'تب سازمانی: مکاتبات با ادارات (ابلاغ، اطلاع‌رسانی، بازداشت‌نامه و ...).',
    ],
  },
  {
    id: 'scoring',
    icon: <EmojiEventsIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#f59e0b',
    title: 'ارزیابی و امتیازدهی',
    content: [
      'امتیازدهی وزنی کارکنان بر اساس ۱۲ معیار:',
      'عملکرد، رضایت شغلی، تحصیلات، حضور و کارکرد، انضباط (جرائم)، مسافت، سابقه، افزایش حقوق، مزایا، مأموریت، قرارداد، نوبت کاری.',
      'رتبه‌بندی با مدال + نوار پیشرفت رنگی + تفکیک جزئیات هر کارمند.',
    ],
  },
  {
    id: 'settings',
    icon: <SettingsIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#64748b',
    title: 'تنظیمات',
    content: [
      'تنظیمات عمومی: ذخیره‌سازی فایل، هشدار، مرخصی و نمایش.',
      'مدیریت کاربران و نقش‌ها.',
      'درون‌ریزی اکسل (بارگذاری گروهی پرسنل/حقوق/مزایا).',
      'ظاهر: ۵ مد — روشن، تاریک، F مود، F مود روشن، کوراساوا (سیاه‌وسفید خالص).',
    ],
  },
  {
    id: 'assistant',
    icon: <SmartToyIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#f43f5e',
    title: 'دستیار منابع انسانی',
    content: [
      'دستیار هوشمند و کاملاً آفلاین — پاسخ از داده‌های واقعی سازمان.',
      'نمونه سؤالات:',
      '• «تاریخ استخدام [نام] کی بوده؟»',
      '• «آدرس [نام] رو بگو»',
      '• «کارکرد [نام] در ۱۴۰۴ چقدر بوده؟»',
      '• «حقوق و مزایای [نام] چقدر بود؟»',
      '• «مزایای رفاهی / مرخصی / جرائم / مدارک / سوابق [نام]»',
      '• «چه کسانی احتمال استعفا دارند؟»',
      '• «بهترین کارمند کیه؟» (رتبه‌بندی)',
      '• «نمودار دپارتمان‌ها رو نشون بده» (تصویر)',
      '• سؤالات مرکب: «کارکرد و حقوق و مزایای [نام] در ۱۴۰۴»',
    ],
  },
  {
    id: 'shortcuts',
    icon: <KeyboardIcon sx={{ color: '#fff', fontSize: 18 }} />,
    color: '#0ea5e9',
    title: 'میانبرهای صفحه‌کلید',
    content: [
      'F1 — باز/بسته کردن این راهنما.',
      'Enter — ارسال پیام در دستیار.',
    ],
  },
];

/* نکات سریع (Quick Tips) */
const QUICK_TIPS = [
  { icon: '🔍', text: 'جستجو در پرسنل: از فیلترهای ترکیبی استفاده کنید' },
  { icon: '📸', text: 'عکس پرسنلی را در تب مدارک آپلود کنید تا همه‌جا نمایش داده شود' },
  { icon: '🎨', text: 'حالت نمایش را از تنظیمات → ظاهر تغییر دهید (حتی کوراساوا!)' },
  { icon: '🤖', text: 'از دستیار با F1 راهنمای سؤالاتش را ببینید' },
  { icon: '📊', text: 'نمودارها را از دستیار با «نمودار ...» درخواست کنید' },
];

const HelpDialog = () => {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');

  useEffect(() => {
    const handler = (e) => {
      if (e.key === 'F1') {
        e.preventDefault();
        setOpen(prev => !prev);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  const normalized = search.trim().toLowerCase();

  const filtered = useMemo(() => {
    let result = HELP_SECTIONS;
    if (activeCategory !== 'all') {
      result = result.filter(s => s.id === activeCategory);
    }
    if (normalized) {
      result = result.filter(s =>
        s.title.toLowerCase().includes(normalized) ||
        s.content.some(c => c.toLowerCase().includes(normalized))
      );
    }
    return result;
  }, [activeCategory, normalized]);

  return (
    <Dialog
      open={open}
      onClose={() => setOpen(false)}
      maxWidth="lg"
      fullWidth
      PaperProps={{ sx: { background: 'transparent', boxShadow: 'none', overflow: 'hidden' } }}
    >
      {/* Glass container */}
      <Paper sx={{
        borderRadius: 4,
        overflow: 'hidden',
        background: 'linear-gradient(135deg, rgba(255,255,255,0.9), rgba(255,255,255,0.7))',
        backdropFilter: 'blur(24px)',
        WebkitBackdropFilter: 'blur(24px)',
        border: '1px solid rgba(255,255,255,0.5)',
      }}>
        {/* Header */}
        <Box sx={{
          px: 3.5, py: 3,
          background: 'linear-gradient(135deg, rgba(99,102,241,0.14), rgba(236,72,153,0.08))',
          borderBottom: '1px solid rgba(99,102,241,0.16)',
          display: 'flex', alignItems: 'center', gap: 2.5,
        }}>
          <Avatar sx={{
            width: 64, height: 64,
            background: 'linear-gradient(135deg, #6366f1, #ec4899)',
            boxShadow: '0 6px 20px rgba(99,102,241,0.4)',
          }}>
            <HelpOutlineIcon sx={{ fontSize: 34, color: '#fff' }} />
          </Avatar>
          <Box sx={{ flex: 1 }}>
            <Typography variant="h5" fontWeight={800}>راهنمای جامع HRMS</Typography>
            <Typography variant="body2" color="textSecondary">
              هر آنچه برای استفاده از سیستم نیاز دارید — همه در یک‌جا
            </Typography>
          </Box>
          <IconButton onClick={() => setOpen(false)} size="large"
            sx={{ border: '1px solid rgba(0,0,0,0.12)', '&:hover': { background: 'rgba(99,102,241,0.08)' } }}>
            <CloseIcon />
          </IconButton>
        </Box>

        <DialogContent sx={{ p: 3.5 }}>
          {/* Search */}
          <TextField
            fullWidth
            size="medium"
            placeholder="جستجو در راهنما... (مثلاً: جستجو، نمودار، دستیار، مرخصی)"
            value={search}
            onChange={e => setSearch(e.target.value)}
            InputProps={{
              startAdornment: <InputAdornment position="start"><SearchIcon color="primary" /></InputAdornment>,
            }}
            sx={{ mb: 2 }}
          />

          {/* Category chips */}
          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2.5 }}>
            <Chip
              label="همه"
              onClick={() => setActiveCategory('all')}
              color={activeCategory === 'all' ? 'primary' : 'default'}
              variant={activeCategory === 'all' ? 'filled' : 'outlined'}
              clickable
            />
            {HELP_SECTIONS.filter(s => s.id !== 'shortcuts').map(s => (
              <Chip
                key={s.id}
                icon={s.icon}
                label={s.title}
                onClick={() => setActiveCategory(activeCategory === s.id ? 'all' : s.id)}
                variant={activeCategory === s.id ? 'filled' : 'outlined'}
                sx={{
                  ...(activeCategory === s.id && {
                    background: s.color,
                    color: '#fff',
                    '& .MuiSvgIcon-root': { color: '#fff' },
                    '&:hover': { background: s.color },
                  }),
                }}
                clickable
              />
            ))}
          </Box>

          {/* Content */}
          {filtered.length === 0 ? (
            <Box textAlign="center" py={6}>
              <HelpOutlineIcon sx={{ fontSize: 56, color: 'text.disabled', mb: 1 }} />
              <Typography color="textSecondary">نتیجه‌ای یافت نشد</Typography>
            </Box>
          ) : (
            <Stack spacing={1.25}>
              {filtered.map(section => (
                <Accordion
                  key={section.id}
                  defaultExpanded={!normalized && activeCategory === 'all'}
                  sx={{
                    borderRadius: 2,
                    background: `linear-gradient(135deg, ${section.color}0d, ${section.color}04)`,
                    border: `1px solid ${section.color}20`,
                    '&:before': { display: 'none' },
                  }}
                >
                  <AccordionSummary expandIcon={<ExpandMoreIcon />}
                    sx={{
                      '& .MuiAccordionSummary-expandIconWrapper': { color: section.color },
                    }}>
                    <Avatar sx={{
                      width: 30, height: 30, mr: 1.5,
                      background: `linear-gradient(135deg, ${section.color}, ${section.color}90)`,
                      boxShadow: `0 2px 8px ${section.color}40`,
                    }}>
                      {section.icon}
                    </Avatar>
                    <Typography fontWeight={700} sx={{ color: section.color }}>
                      {section.title}
                    </Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Stack spacing={0.6}>
                      {section.content.map((c, i) => (
                        <Box key={i} sx={{ display: 'flex', gap: 1 }}>
                          <CheckCircleIcon sx={{ fontSize: 15, color: section.color, mt: '2px', flexShrink: 0 }} />
                          <Typography variant="body2" color="textSecondary">{c}</Typography>
                        </Box>
                      ))}
                    </Stack>
                  </AccordionDetails>
                </Accordion>
              ))}
            </Stack>
          )}

          {/* Quick tips */}
          {activeCategory === 'all' && !normalized && (
            <Box sx={{ mt: 3 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1.5 }}>
                <LightbulbIcon sx={{ color: '#f59e0b' }} />
                <Typography variant="subtitle1" fontWeight={700}>نکات سریع</Typography>
              </Box>
              <Grid container spacing={1.5}>
                {QUICK_TIPS.map((tip, i) => (
                  <Grid item xs={12} sm={6} key={i}>
                    <Paper sx={{
                      p: 1.5, display: 'flex', alignItems: 'center', gap: 1.5,
                      background: 'rgba(255,255,255,0.6)', borderRadius: 2,
                      border: '1px solid rgba(99,102,241,0.12)',
                    }}>
                      <Typography variant="h6">{tip.icon}</Typography>
                      <Typography variant="body2">{tip.text}</Typography>
                    </Paper>
                  </Grid>
                ))}
              </Grid>
            </Box>
          )}
        </DialogContent>

        {/* Footer */}
        <Box sx={{
          px: 3.5, py: 2,
          borderTop: '1px solid rgba(99,102,241,0.12)',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        }}>
          <Chip
            size="small"
            icon={<KeyboardIcon sx={{ fontSize: 14 }} />}
            label="F1 برای باز/بسته کردن"
            variant="outlined"
            sx={{ borderColor: 'rgba(99,102,241,0.3)', color: '#6366f1' }}
          />
          <Button variant="contained" onClick={() => setOpen(false)}>بستن</Button>
        </Box>
      </Paper>
    </Dialog>
  );
};

export default HelpDialog;
